    private static byte[] finish(ByteBuffer b) {
        while (b.position() % 8 != 0) b.put((byte) 0);
        b.putInt(0, b.position());
        byte[] out = new byte[b.position()];
        b.flip();
        b.get(out);
        return out;
    }

    // Values self-pad to 8: they concatenate inside record bodies.
